/**
 * Contrato helpdesk.adjuntos.sesion v1 (src/server/attachments/attachment-broker.ts).
 *
 * Copia de «Impulsa - Sugerencias - Crear sesion de carga V2», con el destino
 * en /me/drive: la credencial de Graph está autorizada como info.admingct@, y
 * su OneDrive es el único destino. Sin driveId que validar, nadie puede
 * apuntar la carga a otra unidad.
 */
const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const required = (value, path) => {
  if (typeof value !== 'string' || !value.trim()) throw new Error(path + ' debe ser un texto no vacío.');
  return value.trim();
};
// El broker no recibe bytes ni URLs: si llegan, el llamador está mal construido.
if (body.uploadUrl !== undefined || body.file?.content !== undefined || body.file?.base64 !== undefined) {
  throw new Error('El broker no acepta binarios, Base64 ni uploadUrl de entrada.');
}
if (body.event !== 'helpdesk.adjuntos.sesion' || Number(body.version) !== 1) throw new Error('Contrato helpdesk.adjuntos.sesion v1 inválido.');
const operationId = required(body.operation?.id, 'operation.id');
const idempotencyKey = required(body.operation?.idempotencyKey, 'operation.idempotencyKey');
const folderPath = required(body.target?.folderPath, 'target.folderPath');
const storedName = required(body.file?.storedName, 'file.storedName');
const sizeBytes = Number(body.file?.sizeBytes);
if (!Number.isSafeInteger(sizeBytes) || sizeBytes <= 0) throw new Error('file.sizeBytes debe ser un entero positivo.');
// Un solo segmento: una barra sacaría el objeto de la carpeta autorizada.
if (storedName.includes('/') || storedName.includes('\\')) throw new Error('file.storedName no puede contener separadores de ruta.');
// Los segmentos se codifican uno a uno: codificar la ruta entera convertiría
// los separadores en %2F y apuntaría a una carpeta con barras en el nombre.
const encodedFolderPath = folderPath.split('/').map((s) => s.trim()).filter(Boolean).map(encodeURIComponent).join('/');
if (!encodedFolderPath) throw new Error('target.folderPath no tiene ningún segmento útil.');
// «fail» y no «rename»: el nombre lleva el id de la carga, así que un choque
// significa que el mismo archivo se sube dos veces, y renombrar dejaría un
// objeto que la confirmación no espera.
return [{ json: { operationId, idempotencyKey, encodedFolderPath, storedName, sizeBytes, conflictBehavior: 'fail' } }];

/**
 * Devuelve la capacidad temporal de carga solo a quien llamó. La URL de
 * carga es una credencial sobre un único objeto: va al navegador, no se
 * guarda, y caduca sola. Por eso el workflow no guarda los datos de sus
 * ejecuciones (settings).
 */
const source = $('Code - Validar sesion').first().json;
const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body ?? {};
if (![200, 201].includes(statusCode) || !body.uploadUrl || !body.expirationDateTime) {
  const message = body?.error?.message ?? ('Graph rechazó createUploadSession con HTTP ' + statusCode + '.');
  return [{ json: { ok: false, operationId: source.operationId, code: statusCode === 429 ? 'THROTTLED' : 'GRAPH_SESSION_FAILED', message: String(message).slice(0, 1000), httpStatus: [400, 401, 403, 404, 409, 429].includes(statusCode) ? statusCode : 502 } }];
}
return [{ json: { ok: true, operationId: source.operationId, idempotencyKey: source.idempotencyKey, session: { expiresAt: body.expirationDateTime, uploadUrl: body.uploadUrl }, httpStatus: 201 } }];

/**
 * Contrato helpdesk.adjuntos.confirmar v1. El navegador terminó la carga, así
 * que es el único que conoce el id del objeto, y también quien menos autoridad
 * tiene para describirlo: aquí solo se comprueba que la petición está bien
 * formada; quien describe el objeto es Graph.
 */
const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const required = (value, path) => {
  if (typeof value !== 'string' || !value.trim()) throw new Error(path + ' debe ser un texto no vacío.');
  return value.trim();
};
// El broker no recibe bytes ni URLs: si llegan, el llamador está mal construido.
if (body.uploadUrl !== undefined || body.file?.content !== undefined || body.file?.base64 !== undefined) {
  throw new Error('El broker no acepta binarios, Base64 ni uploadUrl de entrada.');
}
if (body.event !== 'helpdesk.adjuntos.confirmar' || Number(body.version) !== 1) throw new Error('Contrato helpdesk.adjuntos.confirmar v1 inválido.');
const operationId = required(body.operation?.id, 'operation.id');
const idempotencyKey = required(body.operation?.idempotencyKey, 'operation.idempotencyKey');
const folderPath = required(body.target?.folderPath, 'target.folderPath');
const objectId = required(body.object?.id, 'object.id');
const expectedName = required(body.expected?.storedName, 'expected.storedName');
const expectedSizeBytes = Number(body.expected?.sizeBytes);
if (!Number.isSafeInteger(expectedSizeBytes) || expectedSizeBytes <= 0) throw new Error('expected.sizeBytes debe ser un entero positivo.');
return [{ json: { operationId, idempotencyKey, folderPath, objectId, expectedName, expectedSizeBytes } }];

/**
 * Confirma identidad, carpeta, nombre y tamaño con Graph como autoridad.
 *
 * La carpeta se compara por ruta, porque la sesión se creó contra una ruta.
 * Graph informa el padre como /drive/root:/A/B, codificado y con la caja que
 * guarde la unidad: se quita el prefijo, se decodifica cada segmento y se
 * pasa a minúsculas, como trata OneDrive las rutas. Un objeto que viva en
 * otra carpeta se rechaza aunque exista: lo único que la aplicación autoriza
 * es una carga a la carpeta de adjuntos.
 *
 * El nombre se compara exacto: la sesión se creó con conflictBehavior fail,
 * y el nombre lleva el id de la carga, que es lo que impide confirmar el
 * objeto de otra persona.
 */
const source = $('Code - Validar confirmacion').first().json;
const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body ?? {};
const fail = (code, message, httpStatus) => [{ json: { ok: false, operationId: source.operationId, code, message, httpStatus } }];
if (statusCode !== 200 || !body.id) {
  const message = body?.error?.message ?? ('Graph rechazó la consulta con HTTP ' + statusCode + '.');
  return fail(statusCode === 429 ? 'THROTTLED' : 'GRAPH_CONFIRM_FAILED', String(message).slice(0, 1000), statusCode === 429 ? 429 : (statusCode === 404 ? 404 : 502));
}
if (body.deleted) return fail('OBJECT_DELETED', 'El objeto fue eliminado.', 409);
if (!body.file) return fail('OBJECT_NOT_FILE', 'El objeto no es un archivo.', 409);
const normalizePath = (value) => String(value ?? '')
  .replace(/^\/drives\/[^/]+\/root:?/i, '')
  .replace(/^\/drive\/root:?/i, '')
  .split('/')
  .map((segment) => { try { return decodeURIComponent(segment); } catch { return segment; } })
  .map((segment) => segment.trim())
  .filter(Boolean)
  .join('/')
  .toLowerCase();
if (normalizePath(body.parentReference?.path) !== normalizePath(source.folderPath)) {
  return fail('OBJECT_DESTINATION_MISMATCH', 'El objeto no está en la carpeta de adjuntos.', 409);
}
if (String(body.name ?? '') !== source.expectedName) return fail('OBJECT_NAME_MISMATCH', 'El nombre guardado no coincide con el autorizado.', 409);
if (!Number.isSafeInteger(Number(body.size)) || Number(body.size) !== source.expectedSizeBytes) {
  return fail('OBJECT_SIZE_MISMATCH', 'El tamaño guardado no coincide con el anunciado.', 409);
}
return [{ json: { ok: true, operationId: source.operationId, idempotencyKey: source.idempotencyKey, object: { id: String(body.id), name: String(body.name), sizeBytes: Number(body.size), mimeType: String(body.file?.mimeType ?? '') }, httpStatus: 200 } }];

/**
 * Contrato helpdesk.adjuntos.descarga v1. El id del objeto lo lee HelpDesk de
 * PostgreSQL, nunca del navegador, después de comprobar que la persona puede
 * ver el adjunto (src/app/api/tickets/[idTicket]/adjuntos/[idAdjunto]/route.ts).
 */
const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const required = (value, path) => {
  if (typeof value !== 'string' || !value.trim()) throw new Error(path + ' debe ser un texto no vacío.');
  return value.trim();
};
// El broker no recibe bytes ni URLs: si llegan, el llamador está mal construido.
if (body.uploadUrl !== undefined || body.file?.content !== undefined || body.file?.base64 !== undefined) {
  throw new Error('El broker no acepta binarios, Base64 ni uploadUrl de entrada.');
}
if (body.event !== 'helpdesk.adjuntos.descarga' || Number(body.version) !== 1) throw new Error('Contrato helpdesk.adjuntos.descarga v1 inválido.');
const operationId = required(body.operation?.id, 'operation.id');
const idempotencyKey = required(body.operation?.idempotencyKey, 'operation.idempotencyKey');
const objectId = required(body.object?.id, 'object.id');
return [{ json: { operationId, idempotencyKey, objectId } }];

/**
 * Devuelve @microsoft.graph.downloadUrl: un enlace directo de corta duración,
 * sin cabecera de autorización, así que quien llama nunca recibe una
 * credencial de Graph. HelpDesk lo usa para una redirección y no lo guarda.
 *
 * Sin $select en la consulta, a propósito: Impulsa comprobó (22-sep-2026) que
 * con $select Graph omite la anotación, porque no es una propiedad del
 * driveItem.
 */
const source = $('Code - Validar descarga').first().json;
const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body ?? {};
const fail = (code, message, httpStatus) => [{ json: { ok: false, operationId: source.operationId, code, message, httpStatus } }];
if (statusCode !== 200 || !body.id) {
  const message = body?.error?.message ?? ('Graph rechazó la consulta con HTTP ' + statusCode + '.');
  return fail(statusCode === 429 ? 'THROTTLED' : 'GRAPH_DOWNLOAD_URL_FAILED', String(message).slice(0, 1000), statusCode === 429 ? 429 : (statusCode === 404 ? 404 : 502));
}
if (body.deleted) return fail('OBJECT_DELETED', 'El objeto fue eliminado.', 409);
if (!body.file) return fail('OBJECT_NOT_FILE', 'El objeto no es un archivo.', 409);
const downloadUrl = body['@microsoft.graph.downloadUrl'];
if (typeof downloadUrl !== 'string' || !downloadUrl) return fail('DOWNLOAD_URL_UNAVAILABLE', 'Graph no expuso una URL de descarga.', 502);
return [{ json: { ok: true, operationId: source.operationId, idempotencyKey: source.idempotencyKey, object: { id: String(body.id), downloadUrl }, httpStatus: 200 } }];

/**
 * Contrato helpdesk.adjuntos.vista v1 (U29). Como la descarga: el id del objeto
 * lo lee HelpDesk de PostgreSQL después de comprobar que la persona puede ver
 * el adjunto.
 */
const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const required = (value, path) => {
  if (typeof value !== 'string' || !value.trim()) throw new Error(path + ' debe ser un texto no vacío.');
  return value.trim();
};
// El broker no recibe bytes ni URLs: si llegan, el llamador está mal construido.
if (body.uploadUrl !== undefined || body.file?.content !== undefined || body.file?.base64 !== undefined) {
  throw new Error('El broker no acepta binarios, Base64 ni uploadUrl de entrada.');
}
if (body.event !== 'helpdesk.adjuntos.vista' || Number(body.version) !== 1) throw new Error('Contrato helpdesk.adjuntos.vista v1 inválido.');
const operationId = required(body.operation?.id, 'operation.id');
const idempotencyKey = required(body.operation?.idempotencyKey, 'operation.idempotencyKey');
const objectId = required(body.object?.id, 'object.id');
return [{ json: { operationId, idempotencyKey, objectId } }];

/**
 * Devuelve la URL de vista previa de OneDrive (POST /preview → getUrl): el
 * visor de Microsoft muestra PDF, imágenes y Office dentro de un iframe de
 * HelpDesk, renderizados en sus servidores. Es temporal y no se guarda.
 */
const source = $('Code - Validar vista').first().json;
const response = $input.first()?.json ?? {};
const statusCode = Number(response.statusCode);
const body = response.body ?? {};
if (statusCode !== 200 || typeof body.getUrl !== 'string' || !body.getUrl) {
  const message = body?.error?.message ?? ('Graph no dio vista previa (HTTP ' + statusCode + ').');
  return [{ json: { ok: false, operationId: source.operationId, code: 'GRAPH_PREVIEW_FAILED', message: String(message).slice(0, 1000), httpStatus: statusCode === 404 ? 404 : 502 } }];
}
return [{ json: { ok: true, operationId: source.operationId, idempotencyKey: source.idempotencyKey, object: { previewUrl: body.getUrl }, httpStatus: 200 } }];

/**
 * Contrato helpdesk.adjuntos.organizar v1 (U29). Mueve los adjuntos de un
 * ticket a una carpeta con su código, dentro de la carpeta de adjuntos. Los
 * ids de OneDrive no cambian al mover: la descarga y la vista previa siguen
 * funcionando. Lo llama HelpDesk después de guardar el ticket, y si falla los
 * archivos se quedan en la carpeta general.
 */
const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const required = (value, path) => {
  if (typeof value !== 'string' || !value.trim()) throw new Error(path + ' debe ser un texto no vacío.');
  return value.trim();
};
// El broker no recibe bytes ni URLs: si llegan, el llamador está mal construido.
if (body.uploadUrl !== undefined || body.file?.content !== undefined || body.file?.base64 !== undefined) {
  throw new Error('El broker no acepta binarios, Base64 ni uploadUrl de entrada.');
}
if (body.event !== 'helpdesk.adjuntos.organizar' || Number(body.version) !== 1) throw new Error('Contrato helpdesk.adjuntos.organizar v1 inválido.');
const operationId = required(body.operation?.id, 'operation.id');
const idempotencyKey = required(body.operation?.idempotencyKey, 'operation.idempotencyKey');
const folderPath = required(body.target?.folderPath, 'target.folderPath');
const folderName = required(body.target?.folderName, 'target.folderName');
if (!/^[A-Za-z0-9-]{1,40}$/.test(folderName)) throw new Error('target.folderName debe ser un código de ticket.');
const objects = Array.isArray(body.objects) ? body.objects.map((id) => required(id, 'objects[]')) : [];
if (objects.length === 0 || objects.length > 5) throw new Error('objects debe tener entre 1 y 5 ids.');
// Los segmentos se codifican uno a uno: codificar la ruta entera convertiría
// los separadores en %2F y apuntaría a una carpeta con barras en el nombre.
const encodedFolderPath = folderPath.split('/').map((s) => s.trim()).filter(Boolean).map(encodeURIComponent).join('/');
if (!encodedFolderPath) throw new Error('target.folderPath no tiene ningún segmento útil.');
return [{ json: { operationId, idempotencyKey, encodedFolderPath, folderName, objects } }];

/**
 * La carpeta ya existe (recién creada o de un envío anterior: la creación con
 * «fail» responde 409 y se ignora). Un ítem por objeto que mover.
 */
const source = $('Code - Validar organizar').first().json;
const folder = $input.first()?.json ?? {};
const folderId = folder.body?.id;
if (Number(folder.statusCode) !== 200 || !folderId) {
  return [{ json: { failed: true, objectId: null, message: 'No se encontró la carpeta del ticket.' } }];
}
return source.objects.map((objectId) => ({ json: { objectId, folderId } }));

/** Cuántos se movieron. Un fallo parcial no es un error: el archivo sigue accesible. */
const source = $('Code - Validar organizar').first().json;
const results = $input.all().map((item) => Number(item.json.statusCode));
const moved = results.filter((code) => code === 200).length;
return [{ json: { ok: true, operationId: source.operationId, moved, total: source.objects.length, httpStatus: 200 } }];
